  constructor(source) {
    this.chars = Array.from(source)
    this.pos = 0
    this.line = 1
    this.column = 1
  }

  peek(offset = 0) {
    return this.chars[this.pos + offset]
  }

  atEnd() {
    return this.pos >= this.chars.length
  }

